#!/usr/bin/env bash
set -e
echo "========================================="
echo "📦 Installing pay4u-v2 (Side-by-Side)"
echo "========================================="

# Create isolated directory
mkdir -p /var/www/pay4u-v2
cd /var/www/pay4u-v2

# Extract bundle
echo "Extracting application files..."
cat << 'B64_EOF' | base64 -d | tar -xz

B64_EOF

echo "Files extracted to /var/www/pay4u-v2 successfully!"
echo "Starting service on port 5003 under PM2..."

# Stop previous v2 instance if exists, then start on port 5003
pm2 delete pay4u-v2 2>/dev/null || true
PORT=5003 pm2 start server.js --name "pay4u-v2"
pm2 save

echo "========================================="
echo "✅ pay4u-v2 is now running on PORT 5003!"
echo "========================================="
echo "Status: pm2 status pay4u-v2"
echo "Logs:   pm2 logs pay4u-v2"
echo "Test:   curl http://127.0.0.1:5003/api/summary"
echo "========================================="
